<?php
if(!defined('ABSPATH'))exit;
function bsktv_schema(){if(!is_singular('post'))return;$id=get_the_ID();$title=wp_strip_all_tags(get_the_title());$d=array('@type'=>'Article','headline'=>$title,'url'=>get_permalink(),'datePublished'=>get_the_date('c'),'dateModified'=>get_the_modified_date('c'),'author'=>array('@type'=>'Person','name'=>get_the_author()));if(has_post_thumbnail())$d['image']=get_the_post_thumbnail_url($id,'full');$address=bsktv_meta('bsktv_address');$hours=bsktv_meta('bsktv_hours');$business=array('@type'=>'LocalBusiness','name'=>$title,'url'=>get_permalink());if($address)$business['address']=array('@type'=>'PostalAddress','streetAddress'=>$address);if($hours)$business['openingHours']=$hours;$d['about']=$business;$cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'ids'));$city_name='店家';$city_url=home_url('/');if($cities&&!is_wp_error($cities)){$term=get_term($cities[0],'bsktv_city');if($term&&!is_wp_error($term)){$city_name=$term->name;$city_url=get_term_link($term);}}$graph=array('@context'=>'https://schema.org','@graph'=>array($d,array('@type'=>'BreadcrumbList','itemListElement'=>array(array('@type'=>'ListItem','position'=>1,'name'=>'首頁','item'=>home_url('/')),array('@type'=>'ListItem','position'=>2,'name'=>$city_name,'item'=>$city_url),array('@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>get_permalink())))));echo '<script type="application/ld+json">'.wp_json_encode($graph,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>';}
add_action('wp_head','bsktv_schema',20);
function bsktv_meta_description(){if(!is_singular('post'))return;$text=wp_strip_all_tags(get_the_excerpt());if(!$text)$text=wp_strip_all_tags(get_the_content(null,false));$text=wp_trim_words($text,45,'…');if($text)echo '<meta name="description" content="'.esc_attr($text).'">\n';}add_action('wp_head','bsktv_meta_description',5);
